package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class PublicDecimalRoundingTest {
 @Test public void allSelectedYearFourFiveSixInputsIgnoreAnswerKeys(){int count=0;Checker checker=new Checker();for(int grade=4;grade<=6;grade++){CurriculumLimits limits=GlobalCurriculum.limits("england-primary-2021-v1","el_decimal_round",grade);int places=grade-3,scale=(int)Math.pow(10,places);List<Integer> targets=limits.roundingDecimalTargets();for(int i=0;i<DecimalRoundingSupply.count(limits);i++){Question q=DecimalRoundingSupply.at(limits,i);int target=targets.get(i%targets.size()),n=i/targets.size(),factor=(int)Math.pow(10,places-target);BigDecimal answer=BigDecimal.valueOf((n+factor/2)/factor,target);q.answers=new String[]{"poison"};q.expression="poison";assertTrue(q.prompt,checker.check(q,List.of(),List.of(answer.toPlainString())).correct());assertEquals(Checker.Status.WRONG_ANSWER,checker.check(q,List.of(),List.of(answer.add(BigDecimal.ONE).toPlainString())).status);count++;}}assertEquals(321000,count);}
 @Test public void boundaryAndLegacyPrecisionArePreserved(){Checker c=new Checker();for(String[] item:List.of(new String[]{"99.95","첫째","100.0"},new String[]{"0.04","첫째","0.0"},new String[]{"1.2500","첫째","1.3"},new String[]{"123.4567","둘째","123.46"})){Question q=new Question("el_decimal_round",item[0]+"을 소수 "+item[1]+" 자리까지 반올림하면?","poison","999");q.answerFormat="decimal";assertTrue(c.check(q,List.of(),List.of(item[2])).correct());}Question q=new Question("el_decimal_round","999.5000을 가장 가까운 정수로 반올림하면?","poison","0");q.answerFormat="decimalValue";assertTrue(c.check(q,List.of(),List.of("1000")).correct());assertTrue(c.check(q,List.of(),List.of("1000.00")).correct());}
 @Test public void inputRequirementsAndMalformedQuestionsDoNotUseFallbackKeys(){Question q=new Question("el_decimal_round","1.04을 소수 첫째 자리까지 반올림하면?","poison","1");q.answerFormat="decimal";Checker c=new Checker();assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("1")).status);assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("1/1")).status);assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),Arrays.asList((String)null)).status);assertEquals(Checker.Status.INPUT_NEEDED,c.check(new Question(q.skillId,"broken","","1"),List.of(),List.of("1")).status);assertNull(RoundingRelations.read(new Question(q.skillId,null,"","1")));}
 @Test public void yearFiveFreshQuestionsPreserveBlankHelpAndVersion(){Generator gen=new Generator(new Random(182));var limits=GlobalCurriculum.limits("england-primary-2021-v1","el_decimal_round",5);List<String> recent=new ArrayList<>();Set<Integer> targets=new HashSet<>();for(int i=0;i<100;i++){Question q=gen.next("el_decimal_round",recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());int places=RoundingRelations.read(q).decimalPlaces();targets.add(places);HelpPlan h=HelpPlan.forQuestion(q);assertEquals(places==0?7:8,h.size());assertFalse(h.canTransfer());assertEquals("rounding-relations-v1",q.studyGuide.teachingVersion);assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));}assertEquals(Set.of(0,1),targets);}
}
